use std::fs
use std::env

fn emit(text: string, number: bool, counter: int) -> int {
    let mut n = counter
    if !number {
        print(text)
        return n
    }
    let mut parts: Vec<string> = []
    for p in text.split("\n") {
        parts.push(p)
    }
    let total: int = parts.len() as int
    let mut i: int = 0
    while i < total {
        let last = i == total - 1
        if last && parts[i as usize] == "" {
            break
        }
        n += 1
        let s = "${n}"
        let pad = 6 - (s.len() as int)
        let mut out = ""
        let mut k: int = 0
        while k < pad {
            out = out + " "
            k += 1
        }
        println("${out}${s}\t${parts[i as usize]}")
        i += 1
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter: int = 0
    let mut status: int = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => {
                    counter = emit(t, number, counter)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}
